import numpy as np
from scipy.signal import tf2ss, cont2discrete, ss2tf, lfilter, lsim, lti
from typing import Any


class Solver:
    def solve(self, problem: dict, **kwargs) -> Any:
        num = np.asarray(problem["num"], dtype=np.float64)
        den = np.asarray(problem["den"], dtype=np.float64)
        u = np.asarray(problem["u"], dtype=np.float64)
        t = np.asarray(problem["t"], dtype=np.float64)

        n = len(t)
        if n == 0:
            return {"yout": []}
        if n == 1:
            _, yout, _ = lsim(lti(num, den), u, t)
            return {"yout": yout.tolist()}

        dt = t[1] - t[0]
        is_uniform = np.allclose(np.diff(t), dt, rtol=1e-10, atol=1e-15)

        if is_uniform:
            try:
                A, B, C, D = tf2ss(num, den)
                Ad, Bd, Cd, Dd, _ = cont2discrete((A, B, C, D), dt, method="zoh")
                b, a = ss2tf(Ad, Bd, Cd, Dd)
                yout = lfilter(b, a, u)
            except Exception:
                _, yout, _ = lsim(lti(num, den), u, t)
        else:
            _, yout, _ = lsim(lti(num, den), u, t)

        return {"yout": yout.tolist()}

