import numpy as np
from scipy.signal import cont2discrete, lfilter, lsim, lti
from typing import Any


class Solver:
    def solve(self, problem: dict, **kwargs) -> Any:
        num = np.asarray(problem["num"], dtype=np.float64)
        den = np.asarray(problem["den"], dtype=np.float64)
        u = np.asarray(problem["u"], dtype=np.float64)
        t = np.asarray(problem["t"], dtype=np.float64)

        n = len(t)
        if n <= 1:
            if n == 0:
                return {"yout": []}
            _, yout, _ = lsim(lti(num, den), u, t)
            return {"yout": yout.tolist()}

        dt = t[1] - t[0]
        if not np.allclose(np.diff(t), dt, rtol=1e-10, atol=1e-15):
            raise ValueError("Time steps must be equally spaced")

        try:
            bd, ad, _ = cont2discrete((num, den), dt, method="foh")
            yout = lfilter(bd.ravel(), ad.ravel(), u)
        except Exception:
            _, yout, _ = lsim(lti(num, den), u, t)

        return {"yout": yout.tolist()}

