from scipy.linalg import expm
from scipy.signal import tf2ss


def _build_foh_matrices(A, B, C, D, dt):
    """Build FOH discretization matrices matching scipy.signal.lsim internals."""
    n = A.shape[0]
    m = B.shape[1]

    M = np.vstack(
        [
            np.hstack([A * dt, B * dt, np.zeros((n, m))]),
            np.hstack([np.zeros((m, n + m)), np.eye(m)]),
            np.zeros((m, n + 2 * m)),
        ]
    )
    expMT = expm(M.T)
    Ad = np.ascontiguousarray(expMT[:n, :n].T)
    Bd1 = np.ascontiguousarray(expMT[n + m :, :n].T)
    Bd0 = np.ascontiguousarray(expMT[n : n + m, :n].T - Bd1)

    return Ad, Bd0, Bd1


def _simulate(Ad, Bd0, Bd1, C_vec, D_val, u, y):
    n_states = Ad.shape[0]
    n_steps = len(u)
    x = np.zeros(n_states)
    for i in range(1, n_steps):
        s = 0.0
        for j in range(n_states):
            s += C_vec[j] * x[j]
        y[i - 1] = s + D_val * u[i - 1]
        # x = Ad @ x + Bd0 * u[i-1] + Bd1 * u[i]
        x_new = np.zeros(n_states)
        for j in range(n_states):
            acc = 0.0
            for k in range(n_states):
                acc += Ad[j, k] * x[k]
            x_new[j] = acc + Bd0[j] * u[i - 1] + Bd1[j] * u[i]
        x = x_new
    s = 0.0
    for j in range(n_states):
        s += C_vec[j] * x[j]
    y[-1] = s + D_val * u[-1]


class Solver:
    def solve(self, problem: dict, **kwargs) -> dict:
        num = np.asarray(problem["num"], dtype=np.float64)
        den = np.asarray(problem["den"], dtype=np.float64)
        u = np.asarray(problem["u"], dtype=np.float64)
        t = np.asarray(problem["t"], dtype=np.float64)

        n = len(t)
        if n == 0:
            return {"yout": []}
        if n == 1:
            A, B, C, D = tf2ss(num, den)
            D_val = float(D.ravel()[0])
            return {"yout": [float(D_val * u[0])]}

        dt = t[1] - t[0]
        if not np.allclose(np.diff(t), dt, rtol=1e-10, atol=1e-15):
            raise ValueError("Time steps must be equally spaced")

        A, B, C, D = tf2ss(num, den)
        Ad, Bd0, Bd1 = _build_foh_matrices(A, B, C, D, dt)

        C_vec = np.ascontiguousarray(C.ravel())
        D_val = float(D.ravel()[0])
        Bd0_vec = np.ascontiguousarray(Bd0.ravel())
        Bd1_vec = np.ascontiguousarray(Bd1.ravel())

